var PA_RE_BROKER_ROLES_FLASHCARDS = [
  { front: 'Broker of record', back: 'The individual broker responsible for the real estate transactions of a partnership, association, or corporation that holds a broker\'s license -- the specific licensed person the Commission holds accountable when the "broker" is really a business entity.', source: '49 Pa. Code § 35.201' },
  { front: 'Associate broker', back: 'An individual who holds a broker\'s license but works AS an employee of another broker, rather than running their own brokerage -- a distinct category from both "broker" and "salesperson."', source: '49 Pa. Code § 35.201' },
  { front: 'Branch office', back: 'Any fixed location in Pennsylvania, other than the main office, that a broker or cemetery broker maintains and devotes to real estate business -- each one requires its own separate branch office license.', source: '49 Pa. Code § 35.201, § 35.243' },
  { front: 'Main office (private-residence rule)', back: 'If a broker\'s or cemetery broker\'s main office is located in a private residence, the entrance to the office must be SEPARATE from the entrance to the residence.', source: '49 Pa. Code § 35.242(b)' },
  { front: 'Manager of record', back: 'The rental-listing-referral-agent equivalent of a broker of record: the individual rental listing referral agent responsible for the rental listing transactions of a partnership, association, or corporation holding that license.', source: '49 Pa. Code § 35.201' },
  { front: 'Reciprocal-to-standard conversion trigger', back: 'A reciprocal licensee who moves their principal place of business into Pennsylvania (or loses their standard license in their home state) must notify the Commission within 30 days and obtain a standard PA license by the end of the renewal period.', source: '49 Pa. Code § 35.255(c)' },
  { front: 'Broker price opinion', back: 'An estimate prepared by a broker, associate broker, or salesperson detailing a property\'s probable selling price and condition/market/comparable-sales information -- explicitly does NOT include an automated valuation model.', source: '49 Pa. Code § 35.201' },
  { front: 'Transaction licensee', back: 'A licensee who provides communication or document-preparation services (or performs other broker/salesperson acts) WITHOUT entering into an agency relationship with the consumer -- no loyalty or general confidentiality duty, but still must disclose known material defects.', source: '49 Pa. Code § 35.201, § 35.316' },
];

var PA_RE_BROKER_ESCROW_CONCEPTS_FLASHCARDS = [
  { front: 'Escrow duty in a cobrokerage deal', back: 'If a buyer\'s deposit goes to the SELLING broker rather than the listing broker, the listing broker still generally assumes the escrow duty -- UNLESS the buyer never had proper written prior notice that the selling broker would forward the deposit as the listing broker\'s subagent, in which case the selling broker keeps the duty.', source: '49 Pa. Code § 35.323' },
  { front: 'Nonwaiver of escrow duty', back: 'A broker\'s escrow duty cannot be waived or altered by ANY agreement -- not between the transaction parties, not between the broker and the parties, and not between the broker and any other broker involved in the deal.', source: '49 Pa. Code § 35.322' },
  { front: 'Escrow dispute -- interpleader', back: 'If the parties dispute who\'s entitled to escrowed money, the broker holds the funds until it\'s resolved. If resolution looks unlikely without legal action, the broker may -- after giving 30 days\' notice to the parties -- petition the county court to interplead the rival claimants.', source: '49 Pa. Code § 35.327' },
  { front: 'Rental management account', back: 'A broker acting as a property manager for a lessor is NOT required to hold collected rents in the regular escrow account -- instead, rents go into a SEPARATE rental management account, kept apart from both escrow and general business accounts.', source: '49 Pa. Code § 35.321(b)' },
  { front: 'Escrow records requirement', back: 'A broker must keep records of every escrow-required money receipt -- who it came from, who it belongs to, whose account it\'s deposited for, and the exact dates of receipt, deposit, and withdrawal -- producible to the Commission on request.', source: '49 Pa. Code § 35.328' },
  { front: 'Cemetery-property escrow trigger', back: 'For a cemetery lot/plot sale, the transaction counts as "consummated" for escrow-payout purposes once the buyer receives a COPY of the agreement of sale -- a different, simpler trigger than the recording-opportunity rule that applies to an installment land purchase agreement.', source: '49 Pa. Code § 35.321(c)-(d)' },
];

var PA_RE_BROKER_AGENCY_SUPERVISION_FLASHCARDS = [
  { front: 'Dual agent by supervision (designated agency)', back: 'When a broker designates one licensee to represent the seller/landlord exclusively and a different licensee to represent the buyer/tenant exclusively in the SAME transaction, the broker automatically becomes the dual agent -- simply because the broker supervises both designated agents.', source: '49 Pa. Code § 35.315(e)-(f)' },
  { front: 'Broker\'s duty when supervising designated agents', back: 'On top of the general dual-agent duties, a supervising broker must take reasonable care to protect confidential information disclosed to the designated licensees AND take responsibility for directing/supervising their business activities -- without taking any action adverse to either party.', source: '49 Pa. Code § 35.315(f)' },
  { front: 'Subagent', back: 'A licensee NOT employed by the listing broker who cooperates with the listing broker in selling the property as a seller\'s/landlord\'s agent -- and is deemed, by that cooperation, to have an agency relationship with the SELLER, not a neutral role.', source: '49 Pa. Code § 35.201' },
  { front: 'Extending or delegating an agency relationship', back: 'A broker may NOT extend or delegate the broker\'s own agency relationship to someone else without the principal\'s WRITTEN consent -- the agency doesn\'t automatically transfer just because a different licensee at the firm takes over the file.', source: '49 Pa. Code § 35.311(b)' },
  { front: 'Compensating a cooperating broker', back: 'A broker paying a commission split to another broker who helped market or sell a consumer\'s property does NOT, by itself, create an agency relationship between the consumer and that other (cooperating) broker.', source: '49 Pa. Code § 35.311(c)' },
  { front: 'Seller\'s agent compensating a buyer\'s agent', back: 'A seller\'s agent may compensate a buyer\'s agent (or a transaction licensee) even though that buyer\'s agent does NOT owe the same duties and obligations to the seller/landlord that the seller\'s agent and any subagents do.', source: '49 Pa. Code § 35.312(d)' },
];

var PA_RE_BROKER_DISCIPLINE_CONTINUITY_FLASHCARDS = [
  { front: 'Real Estate Recovery Fund (purpose)', back: 'A fund that exists to reimburse a person who obtained a final civil judgment against a Pennsylvania real estate licensee for fraud, misrepresentation, or deceit in a real estate transaction, and who has been unable to collect the judgment after exhausting all legal and equitable remedies.', source: 'RELRA Chapter 8 (63 P.S. §§ 455.801-455.803); 49 Pa. Code § 35.336' },
  { front: 'Posting a suspension notice', back: 'A broker or cemetery broker whose license is suspended must return the license to the Commission AND post the Commission\'s notice prominently near the public entrance of BOTH the main office and every branch office -- failing to post is itself grounds for further discipline.', source: '49 Pa. Code § 35.291' },
  { front: 'Termination period after a sole-proprietor broker\'s death', back: 'During the termination period, the appointed successor broker may NOT enter new listing agreements and may NOT hire new licensees -- but pending agreements of sale or lease MAY still proceed to consummation, and unexpired listings may be promoted until they expire automatically 90 days after the death.', source: '49 Pa. Code § 35.252(b)' },
  { front: 'Broker\'s failure-to-supervise as its own violation', back: 'A broker who fails to exercise adequate supervision over their licensed salespersons\' activities can be disciplined for that failure ALONE -- the broker doesn\'t need to have personally committed the underlying violation.', source: 'RELRA § 604 (63 P.S. § 455.604)' },
  { front: 'Education-provider approval withdrawal -- hearing procedure', back: 'Before withdrawing a real estate education provider\'s (or director\'s) approval, the Commission must give notice and a hearing under 2 Pa.C.S. §§ 501-508 (Commonwealth agency practice and procedure) -- the Chapter 35 text\'s clearest illustration of the Commission\'s general notice-and-hearing model.', source: '49 Pa. Code § 35.344' },
  { front: 'Office inspection scope', back: 'During a routine or special Commission inspection, the Commission may examine transaction records, inspect all areas of the office, interview licensed and unlicensed employees, AND obtain the broker\'s written authorization letter to the bank so escrow-account records can be released to the Commission.', source: '49 Pa. Code § 35.246(d)' },
  { front: 'Relicensure after revocation', back: 'A revoked licensee cannot be relicensed for at least 5 years after the revocation begins. Even after that floor passes, granting relicensure is entirely within the Commission\'s discretion, and the applicant must still meet CURRENT licensure requirements.', source: '49 Pa. Code § 35.251' },
];

// ============================================================================
// IL RE SALESPERSON (Illinois "Broker" exam, entry-level) -- Key Facts Digest,
// drafted 2026-09-03, sourced from the Real Estate License Act of 2000
// (225 ILCS 454) and the PSI Candidate Information Booklet.
// ============================================================================
var IL_RE_SALESPERSON_LICENSING_RENEWAL_TABLE = {
  headers: ['Fact', 'Real Rule', 'Why It Matters', 'Code Section'],
  rows: [
    ['Category A pre-license education', '75 total class hours: 60 hours of Broker Pre-License Topics + 15 hours of Applied Real Estate Principles-Interactive. Valid for 2 years after satisfactory completion.',
      'The 15-hour "interactive" component is a separate, mandatory piece — completing only the 60-hour topics course doesn\'t satisfy Category A on its own.',
      'PSI Candidate Information Booklet, Illinois License Requirements and Qualifications'],
    ['Post-license education (first broker term)', '45 hours, structured as three separate 15-hour courses — applied brokerage principles, risk management/discipline, and transactional issues — each requiring its OWN 50-question final exam administered by the education provider.',
      'This is on top of the 75-hour pre-license education, not a substitute for it — and each of the three courses has to be separately passed, not just "attended."',
      '225 ILCS 454/5-50(b)'],
    ['Renewal window', 'A license may be renewed within the 90 days preceding its expiration date, by completing continuing education and paying the required fees.',
      'The statute\'s own defined term "renewal period" is literally "the 90 days prior to the expiration date" — a specific, testable window, not "any time before it expires."',
      '225 ILCS 454/5-50(a); definition at 225 ILCS 454/1-10'],
    ['Expired-license ladder', 'Expired ≤2 years: renew normally with fees + continuing education. Expired 2–5 years: must apply, pay the fee, complete CE for the most recently ended license term, AND file proof of fitness. Expired 5+ years: must meet the requirements for a brand-new license.',
      'These are three genuinely different tracks with different requirements — the "just pay a late fee" assumption only holds for the first 2 years.',
      '225 ILCS 454/5-50(c)'],
    ['Continuing education per license term', '12 hours total: a 6-hour core curriculum (which must include at least 2 hours of fair housing training) plus an elective curriculum. Managing brokers must ALSO complete a separate 12-hour broker management CE course.',
      'The 2-hour fair housing minimum is carved out of the 6-hour core specifically — it can\'t be swapped out for a different core subject.',
      '225 ILCS 454/5-70(b), (e)'],
    ['Resident-lessee referral exemption', 'A tenant may refer prospective co-tenants to their landlord WITHOUT a license, but only if: no more than 3 referrals in any 12-month period, compensation capped at the LESSER of $5,000 or 2 months\' rent per 12 months, and the tenant never shows the unit or negotiates lease terms.',
      'All three limits have to hold at once — exceeding any one of them (the referral count, the dollar/rent cap, or the no-showing/no-negotiating line) forfeits the exemption entirely.',
      '225 ILCS 454/5-20(10)'],
  ],
  journalNote: 'The Act itself never states a fixed license "term length" (e.g., "2 years") — Section 5-50(a) explicitly leaves the expiration date and renewal period to be "set by rule," not the statute text. Don\'t treat an assumed term length as a statute-sourced fact; only the 90-day renewal window and the 2/2-5/5-year expired-license ladder above are directly confirmed in the Act\'s own text.',
  sourceNote: 'Source: Illinois Real Estate License Act of 2000 (225 ILCS 454), Sections 1-10, 5-20, 5-50, 5-70, as published by the Illinois General Assembly; PSI Candidate Information Booklet (Illinois Division of Real Estate).',
};

var IL_RE_SALESPERSON_ESCROW_HANDLING_TABLE = {
  headers: ['Fact', 'Real Rule', 'Why It Matters', 'Code Section'],
  rows: [
    ['Special account requirement', 'ALL escrow moneys entrusted to a licensee while acting as a broker, escrow agent, or temporary custodian must be deposited into a special account kept SEPARATE from personal and other business accounts.',
      'Failure to maintain this separation is a standalone, independently listed ground for discipline — not just "best practice."',
      '225 ILCS 454/20-20(a)(17)'],
    ['Interest on the escrow account', 'Noninterest-bearing by DEFAULT — unless the character of the deposit legally requires interest, or the principals to the transaction specifically request, IN WRITING, that it be placed in an interest-bearing account.',
      'A common trap: assuming escrow accounts are always noninterest-bearing. They\'re only required to be, absent one of the two listed exceptions.',
      '225 ILCS 454/20-20(a)(17)'],
    ['Permitted early disbursement', 'Escrow money may be disbursed before the deal is consummated or terminated ONLY: (i) per the principals\' (or their authorized agents\') written direction, (ii) per release/payment terms already written into a contract the principals signed, or (iii) under a court order.',
      'Three specific, exhaustive triggers — a broker can\'t release escrow money early just because it seems reasonable in the moment.',
      '225 ILCS 454/20-20(a)(17)(A)'],
    ['Escrow "abandonment" to the State', 'Escrow money can be deemed abandoned and transferred to the State Treasurer as unclaimed property, but only if: no disbursement under the rule above has happened, no claim has been filed in court, AND 6 months have passed since a principal\'s written demand for the funds.',
      'All three conditions have to be true together — a broker can\'t treat unresolved escrow money as "abandoned" just because a deal fell apart.',
      '225 ILCS 454/20-20(a)(17)(B); Revised Uniform Unclaimed Property Act'],
    ['24-hour document production', 'A licensee must make all escrow records and related documents available to the Department within 24 HOURS of a request by Department personnel.',
      'A real, short, specific deadline — much tighter than the 30-day response window that applies to most other Department information requests.',
      '225 ILCS 454/20-20(a)(18)'],
    ['Special-account record retention', 'Any record relating to a special-account transaction must be kept for a MINIMUM of 5 years; electronic records must be backed up at least monthly.',
      'This 5-year figure applies specifically to special-account/escrow records — don\'t confuse it with other, shorter retention periods elsewhere in real estate practice.',
      '225 ILCS 454/5-45(d)'],
  ],
  sourceNote: 'Source: Illinois Real Estate License Act of 2000 (225 ILCS 454), Sections 5-45(d) and 20-20(a)(17)-(18), as published by the Illinois General Assembly.',
};

var IL_RE_SALESPERSON_DISCIPLINE_PENALTIES_TABLE = {
  headers: ['Ground / Penalty', 'Real Figure or Rule', 'Why It Matters', 'Code Section'],
  rows: [
    ['General discipline fine', 'Up to $25,000 PER VIOLATION, on top of (or instead of) probation, suspension, revocation, or reprimand.',
      'This cap applies per violation, not per case — multiple violations in one matter can each carry their own $25,000 exposure.',
      '225 ILCS 454/20-20(a)'],
    ['Unlicensed-practice civil penalty', 'A SEPARATE civil penalty of up to $25,000 per offense for practicing (or holding oneself out as practicing) without a license — assessed after a hearing, due within 60 days of the order\'s effective date.',
      'A common trap: assuming this is the same $25,000 cap as the general discipline fine above. It is a distinct penalty under a distinct section, aimed specifically at unlicensed activity.',
      '225 ILCS 454/20-10'],
    ['Guaranteed sales plan default', 'A licensee who fails to perform on a guaranteed sales plan exactly per its terms faces all normal Act penalties PLUS a civil fine of up to $25,000 — paid to the INJURED PARTY, not the State.',
      'Unlike the two $25,000 figures above (which go to the Department/State), this one is a private-party payout — a real, distinct type of exposure.',
      '225 ILCS 454/10-50(g)'],
    ['Commingling', 'Mixing the money or property of others with the licensee\'s own money or property is its own standalone discipline ground.',
      'No separate proof that a client was actually harmed is required — commingling alone is enough to trigger discipline.',
      '225 ILCS 454/20-20(a)(22)'],
    ['Interstate reciprocal discipline', 'Being disciplined by ANY other state, the District of Columbia, a territory, a foreign nation, or another authorized government agency is itself an independent Illinois discipline ground — as long as at least one of that discipline\'s grounds matches an Illinois ground.',
      'A licensee can\'t treat out-of-state discipline as "not Illinois\'s problem" — it travels, and a certified copy of the other jurisdiction\'s record is treated as prima facie evidence here.',
      '225 ILCS 454/20-20(a)(5)'],
    ['Cheating on an exam', 'Cheating on (or helping someone else cheat on) the Real Estate License Exam OR a continuing education course/exam is its own standalone discipline ground.',
      'This covers CE exams too, not just the original licensing exam — a distinction that\'s easy to miss.',
      '225 ILCS 454/20-20(a)(7)-(8)'],
  ],
  journalNote: 'Two different $25,000 figures show up in this table for two different reasons (general discipline vs. unlicensed practice) and a THIRD $25,000 figure shows up for a completely different reason (guaranteed sales plan default, paid to a private party). Exam questions love pairing similar-looking dollar figures with different legal triggers — read for WHICH rule produced the number, not just the number itself.',
  sourceNote: 'Source: Illinois Real Estate License Act of 2000 (225 ILCS 454), Sections 10-50(g), 20-10, and 20-20(a), as published by the Illinois General Assembly.',
};

var IL_RE_SALESPERSON_ADDITIONAL_LAWS_TABLE = {
  headers: ['Additional Law', 'How It Reaches a Real Estate Licensee', 'Why It Matters', 'Code Section'],
  rows: [
    ['Illinois Human Rights Act, Article 3', 'Violating ANY provision of Article 3 (real property transactions) is, by itself, an independent License Act discipline ground — regardless of whether the Human Rights Commission has filed or decided a complaint on it.',
      'A licensee can face IDFPR discipline over an Article 3 violation even if no separate Human Rights Commission case ever happens.',
      '225 ILCS 454/20-20(a)(31)'],
    ['Fair housing / anti-steering (License Act\'s own text)', 'Separately from the Human Rights Act cross-reference above, the License Act independently makes it a discipline ground to influence a prospective party, "by any words or acts," so as to promote/maintain racially or religiously segregated housing, or to obstruct racially integrated housing.',
      'This is a SECOND, independent ground covering the same conduct — a licensee could be charged either way, or both.',
      '225 ILCS 454/20-20(a)(30)'],
    ['Sex Offender Registration Act', 'A conviction of, or guilty/nolo contendere plea to, a crime that subjects a licensee to Sex Offender Registration Act compliance is its own independent discipline ground.',
      'Grouped in the same subsection as ordinary felony/misdemeanor convictions, but the statute calls it out separately by name.',
      '225 ILCS 454/20-20(a)(2)(C)'],
    ['Auction License Act', 'Selling or leasing real estate at auction requires EITHER a broker\'s/managing broker\'s license, OR a valid Auction License Act license plus a real estate auction certification under Section 5-32. Even then, the auctioneer\'s own role is limited to setting the time/place/method, advertising, and "crying" the auction — any other brokerage activity (negotiating, closing, etc.) still requires a real estate license.',
      'Holding an auctioneer\'s license does NOT by itself authorize full brokerage activity at a real estate auction — the certification only covers a narrow slice of it.',
      '225 ILCS 454/5-20(13)-(14), 5-32'],
  ],
  journalNote: 'The PSI outline also lists the Illinois Landlord Tenant Act, the Commercial Broker Lien Act, the Radon Resistant Construction Act, and the Illinois Assistance Animal Integrity Act as Additional-Laws exam topics. This project could not locate the text of those specific Acts in a verified primary source -- only the cross-references actually confirmed inside 225 ILCS 454\'s own text are used above.',
  sourceNote: 'Source: Illinois Real Estate License Act of 2000 (225 ILCS 454), Sections 5-20(13)-(14), 5-32, and 20-20(a)(2)(C), (30), (31), as published by the Illinois General Assembly.',
};

var IL_RE_SALESPERSON_DISCLOSURES_TABLE = {
  headers: ['Disclosure', 'When / How It\'s Required', 'Why It Matters', 'Code Section'],
  rows: [
    ['Designated agency disclosure', 'A licensee acting as a designated agent must advise the consumer, IN WRITING, no later than the point they BEGIN working as that consumer\'s designated agent.',
      'The trigger is the start of the working relationship, not the signing of a brokerage agreement — those can be two different moments.',
      '225 ILCS 454/15-35(a)'],
    ['Dual agency consent', 'A licensee (or a sponsoring broker permitting sponsored licensees) may act as a dual agent in the same transaction ONLY with the INFORMED WRITTEN CONSENT of every client involved. The statute spells out specific presumption-of-consent language a signed document can use to satisfy this.',
      'Verbal consent, or consent from only one side, doesn\'t satisfy this — and Illinois law provides an actual model disclosure paragraph, not just a general "get consent" instruction.',
      '225 ILCS 454/15-45(a)'],
    ['Contemporaneous offers', 'Preparing or making contemporaneous competing offers on the same property for different clients does NOT by itself breach a licensee\'s duty — but the licensee must give WRITTEN disclosure to every client involved, and must refer any client who requests it to a different designated agent.',
      'The protection is conditional — skip the written disclosure step and the "no breach" protection doesn\'t apply.',
      '225 ILCS 454/15-15(b)'],
    ['Licensee\'s own-interest disclosure', 'A licensee must disclose, IN WRITING, to ALL parties in a transaction: their status as a licensee, and any interest — direct or indirect — they have or may have in the real estate itself, whenever they\'re buying, selling, leasing, or purchasing any interest in that property.',
      'This applies even to indirect interests, not just outright ownership — a broader trigger than most people assume.',
      '225 ILCS 454/10-27'],
    ['Compensation-source disclosure', 'A licensee must disclose to their client the sponsoring broker\'s compensation policy (including terms, and any amounts offered to cooperating brokers) AND all sources of transaction-related compensation the licensee receives from any third party.',
      'Two separate disclosure duties bundled into one rule — the broker\'s own comp structure, and any outside money flowing to the licensee specifically.',
      '225 ILCS 454/10-10(a)-(b)'],
    ['Dual-side compensation & referral-interest disclosure', 'If a sponsoring broker is compensated by BOTH sides of one transaction, that fact must be disclosed in writing to the client. Separately, if a licensee refers a client to a service provider in which the licensee holds more than a 1% ownership interest (or from which they get profit-sharing), that must be disclosed AT THE TIME of the referral.',
      'The 1% threshold is a real, specific figure — a small ownership stake still triggers the disclosure duty, it doesn\'t take a controlling interest.',
      '225 ILCS 454/10-10(c)-(d)'],
  ],
  sourceNote: 'Source: Illinois Real Estate License Act of 2000 (225 ILCS 454), Sections 10-10, 10-27, 15-15(b), 15-35, and 15-45, as published by the Illinois General Assembly.',
};

var IL_RE_SALESPERSON_KEY_TERMS_FLASHCARDS = [
  { front: 'Client vs. Customer', back: 'Two distinct statutory categories: a "client" is a person being REPRESENTED by a licensee; a "customer" is a consumer who is NOT being represented. The duties owed differ sharply between the two.', source: '225 ILCS 454/1-10' },
  { front: 'Designated agency / designated agent', back: 'A "designated agency" is the contractual relationship between a sponsoring broker and a client where one or more of the broker\'s licensees are named as that client\'s legal agent. The "designated agent" is that specifically-named sponsored licensee — not every licensee at the firm.', source: '225 ILCS 454/1-10, 15-50' },
  { front: 'Dual agency (Illinois-specific twist)', back: 'A licensee representing both buyer and seller (or landlord and tenant) in one deal. When the relationship is a designated agency, whether dual agency exists is judged by the DESIGNATED AGENT\'s own relationships — not by the sponsoring broker\'s overall relationships with both sides.', source: '225 ILCS 454/1-10' },
  { front: 'Escrow moneys — statutory definition', back: 'Includes earnest money and most security deposits — but specifically EXCLUDES a security deposit where the person holding it is also the SOLE OWNER of the property being leased. A landlord holding their own tenant\'s deposit on their own solely-owned property isn\'t handling "escrow moneys" in the Act\'s technical sense.', source: '225 ILCS 454/1-10' },
  { front: 'Managing broker — self-sponsorship', back: 'A managing broker "may act as one\'s own sponsor" — a managing broker doesn\'t necessarily need a separate sponsoring broker over them the way a broker does.', source: '225 ILCS 454/1-10' },
  { front: '"Team" — statutory definition', back: 'Two or more licensees who work together, hold themselves out publicly as a team/group under a team name DIFFERENT from their sponsoring broker\'s name, and are all supervised by the same managing broker and sponsored by the same sponsoring broker. A "team" is explicitly NOT a separately organized or incorporated legal entity.', source: '225 ILCS 454/1-10' },
  { front: 'Residential leasing agent — 120-day provisional window', back: 'A person can engage in residential leasing activity for up to 120 CONSECUTIVE DAYS without yet holding the license — but only if a sponsoring broker is supervising, the Department has been notified the person is pursuing licensure, and the person enrolls in the pre-license education course within 60 days of starting.', source: '225 ILCS 454/5-5(d)' },
  { front: 'Broker — the statutory "pattern of business" test', back: 'Beyond the obvious sale/lease/negotiate activities, a person also counts as acting as a "broker" if they engage in a PATTERN of buying, selling, or dealing in real estate contracts — defined as 2 or more such occasions in any 12-month period, alone or with others.', source: '225 ILCS 454/1-10(5)' },
];

var IL_RE_SALESPERSON_LICENSE_EXEMPTIONS_FLASHCARDS = [
  { front: 'Owner/lessor exemption', back: 'An owner or lessor of real property (or their regular employee, acting within the scope of managing/selling/investing that property) doesn\'t need a license — but ONLY for property they actually own or lease. The exemption evaporates the moment they perform licensed activity for property they don\'t own or lease.', source: '225 ILCS 454/5-20(1)' },
  { front: 'Attorney-in-fact / attorney-at-law exemption', back: 'Two distinct exemptions bundled together: (1) an attorney-in-fact acting under a duly executed and RECORDED power of attorney to convey real estate, and (2) an attorney at law performing the actual duties of an attorney at law.', source: '225 ILCS 454/5-20(2)' },
  { front: 'Fiduciary/court-authority exemption', back: 'A person acting as a receiver, bankruptcy trustee, administrator, executor, or guardian — or otherwise acting under a court order or the authority of a will/testamentary trust — doesn\'t need a real estate license to handle the property involved.', source: '225 ILCS 454/5-20(3)' },
  { front: 'On-site resident manager exemption', back: 'A resident manager of an apartment building, duplex, or apartment complex is exempt from licensure for leasing that property — but only if the unit they manage is genuinely their own PRIMARY RESIDENCE, and they actually live on the premises.', source: '225 ILCS 454/5-20(4)' },
  { front: 'Government-officer exemption', back: 'Officers and employees of a federal agency, or of Illinois state government or any of its political subdivisions, are exempt from licensure while performing their OFFICIAL duties — the exemption is tied to acting in that official capacity, not to the person generally.', source: '225 ILCS 454/5-20(5)-(6)' },
  { front: 'MLS exemption', back: 'A multiple listing service (or similar information exchange) is exempt from licensure for collecting/disseminating real estate listing information to licensees — but ONLY if no OTHER licensed activity is bundled in alongside that information-sharing function.', source: '225 ILCS 454/5-20(7)' },
  { front: 'Advertising-medium exemption', back: 'A medium of advertising (a publisher, platform, etc.) is exempt from licensure for routinely selling or publishing real estate ads — again, ONLY as long as no other licensed activity comes bundled with the advertising.', source: '225 ILCS 454/5-20(9)' },
  { front: 'Short-term/hotel-tax rental exemption', back: 'A person renting out a room (or all/part of their residence via an online marketplace) is exempt from real estate licensure if they\'re registered with the Illinois Department of Revenue and pay Hotel Operators\' Occupation Tax — capped at NOT MORE THAN 30 consecutive days AND not more than 60 days total in a calendar year.', source: '225 ILCS 454/5-20(15)' },
];

var IL_RE_SALESPERSON_BUSINESS_PRACTICES_FLASHCARDS = [
  { front: 'Payment-of-compensation chain', back: 'A licensee generally cannot pay compensation directly to another sponsoring broker\'s sponsored licensee, and a sponsored licensee generally cannot accept compensation from anyone but their OWN sponsoring broker — compensation is supposed to flow through the sponsoring-broker relationship, with only narrow listed exceptions.', source: '225 ILCS 454/10-5' },
  { front: 'One-sponsoring-broker rule', back: 'A licensee may perform licensed activities only for their OWN sponsoring broker, and may have only ONE sponsoring broker at any given time — no splitting activity across two sponsoring brokers simultaneously.', source: '225 ILCS 454/10-20(a)' },
  { front: 'Business-entity compensation exception', back: 'A sponsoring broker may pay compensation directly to a business entity the licensee solely owns (formed just to receive that compensation) without that entity itself needing to be licensed — as long as it\'s owned solely by the licensee, or by the licensee and their spouse if both are licensed and sponsored by the same broker.', source: '225 ILCS 454/10-20(e)' },
  { front: 'No compensation to unlicensed persons', back: 'No compensation may be paid to an unlicensed person in exchange for that person performing activities that require a license under the Act — a flat rule with no "just this once" exception for licensed activity performed by someone unlicensed.', source: '225 ILCS 454/10-15(a)' },
  { front: 'Out-of-state/foreign broker cooperation exception', back: 'Nothing in the Act prohibits cooperating with, or paying compensation to, a broker licensed and domiciled in another state or country — as long as that person is properly licensed (or exempt) where THEY practice and complies with their own jurisdiction\'s law.', source: '225 ILCS 454/10-10(e)' },
  { front: 'Brokerage agreement auto-expiration rule', back: 'Every written brokerage agreement must either auto-expire within a definite period, OR — if longer than one year — give the client an annual right to terminate on no more than 30 days\' written notice. An agreement missing BOTH of those features is VOID outright, not just unenforceable in part.', source: '225 ILCS 454/10-25' },
  { front: '"Solely owned" / "By Owner" advertising', back: 'A sponsored or inactive licensee may advertise "By Owner" only for property they SOLELY own — meaning: 100% ownership alone, OR ownership as a joint tenant/tenant by the entirety, OR a 100% beneficial interest in a land trust. Even then, "broker owned"/"agent owned" disclosure is still required.', source: '225 ILCS 454/10-30(c)(2)' },
  { front: 'CMA/BPO required written elements', back: 'A broker price opinion or comparative market analysis must be written and must include: its intended purpose, a description of the property, the methodology used, any assumptions/limiting conditions, disclosure of the broker\'s own interest (if any), and the broker\'s name/license number/signature — plus a required statement that it is NOT an appraisal.', source: '225 ILCS 454/10-45(b)' },
];

var IL_RE_SALESPERSON_AGENCY_LIABILITY_FLASHCARDS = [
  { front: 'Vicarious liability shield', back: 'A consumer is NOT vicariously liable for the acts or omissions of the licensee providing services for or on their behalf — a client can\'t be dragged into legal responsibility just because their own agent did something wrong.', source: '225 ILCS 454/15-60' },
  { front: 'No subagency through an MLS', back: 'A broker is not automatically a subagent of another broker\'s client merely by being a member of the same MLS or similar information exchange — and an offer of subagency can\'t even be MADE through an MLS in the first place.', source: '225 ILCS 454/15-55' },
  { front: 'Article 15 statute of limitations', back: 'A private lawsuit under the Agency Relationships article is barred unless brought within 2 years of when the person knew (or reasonably should have known) of the act or omission — and in no event more than 5 YEARS after the act or omission itself, though the clock pauses for a minor or someone under legal disability.', source: '225 ILCS 454/15-70(b)' },
  { front: 'Exclusive brokerage agreement — minimum services', back: 'Every exclusive brokerage agreement must be in writing and guarantee, at minimum: accepting and presenting offers/counteroffers, helping negotiate and communicate through to a signed deal with contingencies resolved, and answering the client\'s questions about all of that.', source: '225 ILCS 454/15-75' },
  { front: 'Duties after termination', back: 'Once a brokerage agreement ends, a sponsoring broker and their licensees owe NO further duties to that former client — EXCEPT accounting for all money/property tied to the transaction, and keeping any confidential information confidential.', source: '225 ILCS 454/15-30' },
  { front: 'Compensation does not determine agency', back: 'The mere fact that a licensee is paid, or promised payment, by a particular party does NOT by itself establish (or rule out) an agency relationship with that party — compensation and representation are legally separate questions.', source: '225 ILCS 454/15-40' },
  { front: 'Index of decisions', back: 'The Department is required to keep a PUBLIC index of every formal decision on license issuance, refusal to issue, renewal, refusal to renew, revocation, suspension, and other disciplinary/probationary action — available during regular business hours.', source: '225 ILCS 454/20-5' },
  { front: 'Attorney-licensee dual-role conflict', back: 'A licensee who is ALSO an attorney may not act as the attorney for either the buyer or the seller in a transaction where that same person is acting (or has acted) as the managing broker or broker — a specific, standalone discipline ground.', source: '225 ILCS 454/20-20(a)(34)' },
];

// ============================================================================
// IL RE BROKER (Illinois "Managing Broker" exam, upgrade tier) -- Key Facts
// Digest, drafted 2026-09-03, sourced from 225 ILCS 454 at managing-broker level.
// ============================================================================
var IL_RE_BROKER_SUPERVISION_TABLE = {
  headers: ['Duty', 'Real Rule', 'Why It Matters', 'Code Section'],
  rows: [
    ['Written company policy', 'Every brokerage company or entity (other than a sole proprietorship with no other sponsored licensees) must adopt a written company/office policy covering topics including agency, fair housing, confidentiality, advertising, training/supervision of sponsored licensees, required disclosures, risk management, and the handling of earnest money and escrows.',
      'Eight specific topics are named in the statute itself, not left to the broker\'s discretion -- and having no written policy at all is independently disciplinable.',
      '225 ILCS 454/10-40'],
    ['Supervision of special accounts', 'The designated managing broker is responsible for, and must supervise, ALL of the company\'s special accounts -- not just the ones tied to transactions the DMB personally worked.',
      'This duty attaches to the DMB\'s TITLE, not to personal involvement in a given deal -- a DMB can be on the hook for an account they never personally touched.',
      '225 ILCS 454/10-55(a)'],
    ['Direct handling before 45 hours of post-license education', 'The designated managing broker must personally handle all earnest money, escrows, and contract negotiations for any transaction where the designated agent has NOT yet completed the 45 hours of broker post-license education -- and must personally approve that agent\'s advertisements too.',
      'A newly licensed broker who hasn\'t finished the 45-hour post-license curriculum has NO authority to bind the sponsoring broker at all -- a real legal capacity limit, not just a training recommendation.',
      '225 ILCS 454/10-55(b)'],
    ['Sponsorship notice window', 'The sponsoring broker must notify the Department within 24 hours after establishing a new sponsorship, and within 24 hours after a sponsorship terminates (whichever side initiates the termination).',
      'Missing the termination notice is its own separate discipline ground under Section 20-20 -- independent of whatever caused the licensee to leave.',
      '225 ILCS 454/5-40(a)-(b)'],
    ['Temporary practice authorization', 'If an office loses its designated managing broker and isn\'t replaced, a written request for authorization to keep operating must go to the Department within 15 days of the loss. Any authorization granted is valid for no more than 60 days, unless extended by the Department for good cause.',
      'A real, tight timeline -- an office can\'t just keep running indefinitely on autopilot after losing its DMB.',
      '225 ILCS 454/5-29'],
    ['Discipline exposure for the DMB personally', 'A designated managing broker\'s failure to provide an appropriate written company policy, or failure to perform any of the Section 10-55 supervisory duties, is itself listed as an independent ground for discipline against the DMB.',
      'This is a violation the DMB commits just by NOT supervising -- no underlying fraud, misrepresentation, or client harm has to be proven separately.',
      '225 ILCS 454/20-20(a)(46)'],
  ],
  journalNote: 'Notice the split: Section 10-55 creates the supervisory DUTY, but it\'s Section 20-20(a)(46) that turns failing that duty into a listed, independently disciplinable violation. Exam questions can test either section in isolation -- know both citations, not just the underlying rule.',
  sourceNote: 'Source: Illinois Real Estate License Act of 2000, 225 ILCS 454, Sections 5-29, 5-40, 10-40, 10-55, and 20-20(a)(46), as published by the Illinois General Assembly (ilga.gov).',
};

var IL_RE_BROKER_ESCROW_TABLE = {
  headers: ['Rule', 'Real Requirement', 'Why It Matters', 'Code Section'],
  rows: [
    ['Where escrow money must sit', 'All escrow moneys belonging to others must be deposited in a special account, separate and apart from personal and other business accounts, and kept there until the transaction is consummated or terminated.',
      'This is a standalone, listed discipline ground on its own -- failing to maintain the separate account is enough, whether or not the money was ever actually misused.',
      '225 ILCS 454/20-20(a)(17)'],
    ['Interest on the account', 'The account must be noninterest-bearing UNLESS the character of the deposit legally requires interest, or the principals to the transaction specifically require in writing that it be placed in an interest-bearing account.',
      'The default is NO interest -- interest-bearing is the exception, and it takes an affirmative written request to get there.',
      '225 ILCS 454/20-20(a)(17)'],
    ['Lawful ways to release funds before closing', 'Before the deal is consummated or terminated, escrow money may only be disbursed (i) per the principals\' written direction, (ii) per release/payment terms already written into a signed contract, or (iii) pursuant to a court order.',
      'Only three lawful paths exist -- a broker "using their judgment" to release funds early on their own authority isn\'t one of them.',
      '225 ILCS 454/20-20(a)(17)(A)'],
    ['When escrow money can be treated as abandoned', 'Escrow money can be deemed abandoned and transferred to the State Treasurer as unclaimed property only if: no lawful disbursement has occurred, no court claim has been filed, AND 6 months have passed since a written demand for the money from one of the principals.',
      'All three conditions have to be true together -- a broker can\'t sweep disputed funds to the Treasurer just because a deal has been sitting stale for a while.',
      '225 ILCS 454/20-20(a)(17)(B)'],
    ['Producing escrow records to the Department', 'All escrow records and related documents connected to the practice of real estate must be made available to Department personnel within 24 hours of a request.',
      'A genuinely short window compared to most other Department deadlines in this Act -- don\'t confuse it with the separate 30-day window for general information requests.',
      '225 ILCS 454/20-20(a)(18)'],
    ['Commingling', 'Mixing the money or property of others with the licensee\'s own money or property is its own listed, standalone ground for discipline.',
      'No separate proof of client harm is required -- the act of commingling alone is enough to trigger discipline.',
      '225 ILCS 454/20-20(a)(22)'],
  ],
  sourceNote: 'Source: Illinois Real Estate License Act of 2000, 225 ILCS 454, Section 20-20(a)(17), (18), and (22), as published by the Illinois General Assembly (ilga.gov).',
};

var IL_RE_BROKER_LICENSING_RENEWAL_TABLE = {
  headers: ['Fact', 'Real Rule', 'Why It Matters', 'Code Section'],
  rows: [
    ['Managing broker education, Category A-2 path', 'An applicant who already holds an active Illinois broker license, held for at least 2 of the preceding 3 years, must complete 45 additional class hours (30 hours Managing Broker Pre-License Topics + 15 hours Applied Management and Supervision) within the year immediately before applying.',
      'The 45-hour figure is what most people mean by "managing broker education," but it only applies on TOP OF an active broker license already held 2 of the last 3 years -- it isn\'t the whole requirement by itself.',
      '225 ILCS 454/5-28(a)(3)-(5)'],
    ['Total hours without an active broker license (Category A-1)', 'An applicant who is NOT currently an active Illinois broker must complete 165 total class hours: the 120 broker pre/post-license hours PLUS the same 45 managing-broker-specific hours.',
      'Two very different real hour-counts (45 vs. 165) depending on whether the applicant already holds an active broker license -- a classic trap for mixing these up.',
      '225 ILCS 454/5-28(a)(5); PSI Candidate Information Booklet'],
    ['Exam retake limit', 'Candidates get up to 4 attempts to pass the Managing Broker exam within their 2-year eligibility period. After a 4th failure, the candidate must repeat the required pre-license education before a 5th attempt (treated as a brand-new application).',
      'The number is the SAME 4-attempt structure used for the broker and residential leasing agent exams -- but the required re-education differs depending on which exam it is.',
      '225 ILCS 454/5-35(c); PSI Candidate Information Booklet'],
    ['Licensure by endorsement (managing broker)', 'Requires an active managing-broker license (or equivalent) held in another state, at least 2 years of active practice there immediately before applying, an official good-standing statement from that state\'s licensing authority, passing an Illinois-law-specific test, and completing a 30-hour Department-approved endorsement course.',
      'Endorsement candidates skip the 165/45-hour Illinois curriculum entirely -- but the 2-years-active and Illinois-law-test requirements are not waived for anyone.',
      '225 ILCS 454/5-60.5(a)'],
    ['Continuing education per renewal term', 'Renewing managing brokers must complete 12 hours of general real estate CE PLUS a separate 12-hour broker management CE course (24 hours total) -- with at least 2 of the 6 core-curriculum hours specifically devoted to fair housing training.',
      'The 12-hour broker management course is IN ADDITION to the general 12 hours, not a subset of it -- managing brokers carry a real CE load brokers alone don\'t.',
      '225 ILCS 454/5-70(b), (e)'],
    ['Reinstating an expired license', 'Expired less than 2 years: ordinary renewal (fees + CE). Expired 2-5 years: formal restoration (fee, CE for the most recent completed term, and proof of fitness). Expired more than 5 years: must meet the requirements for an entirely new license.',
      'Three genuinely different real tiers based on how long the license has been lapsed -- not a single uniform "reinstatement" process.',
      '225 ILCS 454/5-50(c)'],
  ],
  sourceNote: 'Source: Illinois Real Estate License Act of 2000, 225 ILCS 454, Sections 5-28, 5-35, 5-50, 5-60.5, and 5-70, as published by the Illinois General Assembly (ilga.gov); PSI Services LLC Candidate Information Booklet for the IDFPR Division of Real Estate.',
};

var IL_RE_BROKER_RECOVERY_FUND_TABLE = {
  headers: ['Fact', 'Real Rule', 'Why It Matters', 'Code Section'],
  rows: [
    ['Fund target balance', 'The Real Estate Recovery Fund is maintained at a $1,000,000 balance: whenever the balance drops below $900,000, the State Treasurer transfers money in from the Real Estate License Administration Fund to bring it back to $1,000,000. Any balance above $1,000,000 gets swept back out to the Administration Fund.',
      'This is a real, current statutory dollar figure -- the Fund\'s TARGET size -- which is different from (and shouldn\'t be confused with) any individual claimant\'s payout cap.',
      '225 ILCS 454/25-35'],
    ['Deadline to start a recovery action', 'An action for a judgment that could lead to Fund collection must be started no later than 2 years after the aggrieved person knew, or through reasonable diligence should have known, of the violation.',
      'The clock runs from DISCOVERY (actual or constructive), not necessarily from the date of the underlying act itself.',
      '225 ILCS 454/20-90(a)'],
    ['Must name every responsible party as a defendant', 'The aggrieved person must name as defendants ALL licensees, employees, or independent contractors allegedly responsible for the loss. Failing to name any of them precludes recovery from the Fund on that judgment entirely.',
      'A real, harsh all-or-nothing consequence -- leaving out even one responsible party can wipe out the entire Fund claim, regardless of how strong the case is against the others.',
      '225 ILCS 454/20-90(b)'],
    ['No interest on the recovered amount', 'The post-judgment order paid from the Fund does not include interest on the underlying judgment.',
      'A claimant collects the principal loss amount only from the Fund -- any interest that accrued on the judgment itself isn\'t part of what the Fund pays.',
      '225 ILCS 454/20-85'],
    ['Post-judgment notice window', 'The aggrieved person must give the Department written notice within 30 days of the judgment being entered, and must give the Department 20 days\' prior written notice of any supplementary proceedings.',
      'Two separate real deadlines in the same process -- 30 days after judgment, 20 days before supplementary proceedings -- easy to transpose on an exam.',
      '225 ILCS 454/20-90(f)'],
    ['Per-claim dollar caps are set by rule, not by the statute', 'The statute caps recovery at "an amount... as adopted by rule" both per act/transaction and per licensee -- 225 ILCS 454 itself does not state a specific dollar figure for either cap.',
      'Unlike some other states, where the recovery-fund payout caps are written directly into the statute\'s own text, Illinois delegates that specific number to Department rule (68 Ill. Admin. Code 1450) -- know that the number lives in rule, not in the Act itself.',
      '225 ILCS 454/20-85'],
  ],
  sourceNote: 'Source: Illinois Real Estate License Act of 2000, 225 ILCS 454, Sections 20-85, 20-90, and 25-35, as published by the Illinois General Assembly (ilga.gov).',
};

var IL_RE_BROKER_DISCIPLINE_PENALTIES_TABLE = {
  headers: ['Penalty', 'Real Figure/Rule', 'Why It Matters', 'Code Section'],
  rows: [
    ['Fine ceiling per violation', 'The Department may impose a fine of up to $25,000 for EACH violation, in addition to refusing/suspending/revoking the license, probation, reprimand, or other disciplinary action -- across the Act\'s full list of 47+ enumerated discipline grounds.',
      'It\'s PER violation, not a single flat cap -- multiple grounds found in one case can each carry their own $25,000 exposure.',
      '225 ILCS 454/20-20(a)'],
    ['Unlicensed practice civil penalty', 'A civil penalty of up to $25,000 per offense for practicing (or holding oneself out to practice) as a managing broker, broker, or residential leasing agent without a license -- due within 60 days of the order, which is itself enforceable as a court judgment.',
      'Same $25,000 ceiling as the general discipline fine, but this is a SEPARATE penalty aimed specifically at unlicensed activity, with its own 60-day payment deadline.',
      '225 ILCS 454/20-10'],
    ['Guaranteed sales plan default fine', 'A licensee who fails to perform a guaranteed sales plan in strict accordance with its terms is subject to a civil fine of up to $25,000 -- payable directly to the party injured by the default, not to the Department.',
      'A third distinct $25,000 figure with a different recipient (the injured party, not the state) -- don\'t assume every discipline-adjacent fine in this Act goes to the Department.',
      '225 ILCS 454/10-50(g)'],
    ['Returned payment fee', 'A $50 fee applies when a check or credit card payment made to the Department is returned or dishonored.',
      'A small, specific, real number that\'s easy to overlook next to the larger discipline fines -- but a real, separately testable figure.',
      '225 ILCS 454/20-25'],
    ['Renewal blocked by unpaid fines', 'The Department will not issue or renew ANY license if the applicant/licensee has an unpaid disciplinary fine, non-disciplinary fee, or unlicensed-practice civil penalty -- unless it\'s paid in full or the licensee is current on an approved payment plan.',
      'This blocks renewal categorically, regardless of how minor the underlying fine was or how long ago it was imposed.',
      '225 ILCS 454/5-50(h)-(i)'],
    ['Exam cheating as a discipline ground', 'Cheating on (or attempting to subvert) the license exam or a CE course/exam, AND separately aiding or abetting another applicant\'s cheating, are each independently listed grounds for discipline.',
      'Two separate listed violations, not one -- a licensee who helps someone else cheat is disciplinable on that ground alone, even without personally cheating.',
      '225 ILCS 454/20-20(a)(7)-(8)'],
  ],
  sourceNote: 'Source: Illinois Real Estate License Act of 2000, 225 ILCS 454, Sections 5-50, 10-50(g), 20-10, 20-20(a), and 20-25, as published by the Illinois General Assembly (ilga.gov).',
};

var IL_RE_BROKER_SUPERVISION_TERMS_FLASHCARDS = [
  { front: 'Designated managing broker', back: 'A managing broker who has supervisory responsibilities for licensees in one office (or, at a multi-office company, more than one office) and has been formally appointed as such by the sponsoring broker, registered with the Department.', source: '225 ILCS 454/1-10' },
  { front: 'Managing broker (self-sponsorship)', back: 'A managing broker license lets the holder act as their OWN sponsor -- a real distinction from a plain broker license, which cannot self-sponsor.', source: '225 ILCS 454/1-10' },
  { front: 'Sponsoring broker', back: 'The broker who certifies to the Department that they sponsor a given managing broker, broker, or residential leasing agent -- the certification itself, once registered, is what creates the "sponsorship."', source: '225 ILCS 454/1-10' },
  { front: 'Team', back: 'Two or more licensees who work together under a team name DIFFERENT from their sponsoring broker\'s name, present themselves publicly as a team, and are all supervised by the same managing broker and sponsored by the same sponsoring broker. A "team" is explicitly NOT a separate legal entity.', source: '225 ILCS 454/1-10' },
  { front: '"Designated managing broker" title restriction', back: 'Only the specific individual appointed and registered as the designated managing broker of an office may identify themselves to the public as a "designated managing broker" in advertising. Other managing-broker license holders may call themselves "managing broker" -- but not "designated managing broker."', source: '225 ILCS 454/10-30(g)' },
  { front: 'Escrow moneys (statutory definition)', back: 'All moneys, promissory notes, or other financial consideration deposited for the benefit of the transaction\'s parties -- includes earnest money and security deposits, EXCEPT a security deposit held by a landlord who is also the sole owner of the leased property.', source: '225 ILCS 454/1-10' },
  { front: 'When a "transaction" legally begins', back: 'For escrow-money purposes, a transaction exists once an agreement has been reached and an accepted real estate contract is signed, or a lease is agreed to, by the parties -- that\'s the specific trigger point escrow obligations attach to.', source: '225 ILCS 454/1-10' },
  { front: 'Inactive license status', back: 'A license that still exists but can\'t be used because the licensee is unsponsored, or because the sponsoring broker\'s own license has become expired, revoked, or suspended. The licensee is prohibited from practicing until a valid new sponsorship is registered.', source: '225 ILCS 454/1-10' },
];

var IL_RE_BROKER_AGENCY_CONCEPTS_FLASHCARDS = [
  { front: 'Material facts (statutory scope)', back: 'Facts about the transaction the licensee actually knows, which the licensee must disclose to their own client -- but the definition EXCLUDES physical conditions on unrelated property that don\'t substantially hurt value, and unrelated fact-situations or occurrences at the property.', source: '225 ILCS 454/15-15(a)(2)(C)' },
  { front: 'Stigmatized property (Illinois\'s specific carve-out)', back: 'No cause of action arises against a licensee for failing to disclose that an occupant had HIV or another medical condition, or that the property was the site of an act/occurrence with no effect on its physical condition -- a specific statutory protection, not just general practice.', source: '225 ILCS 454/15-20' },
  { front: 'Duties after termination of a brokerage agreement', back: 'Once a brokerage agreement ends, a licensee\'s remaining duties shrink to exactly two things: accounting for all money/property related to the transaction, and keeping confidential information confidential. Everything else ends with the agreement.', source: '225 ILCS 454/15-30' },
  { front: 'Compensation does not determine agency', back: 'Who pays a licensee -- or promises to pay them -- is NOT what decides whether an agency relationship exists between that licensee and a consumer. A common wrong-answer trap on agency questions.', source: '225 ILCS 454/15-40' },
  { front: 'Dual agency informed consent', back: 'Requires the INFORMED WRITTEN consent of every client. That consent is only presumed given when the client signs a specific statutory-form disclosure document laying out the conflict-of-interest risks -- not just any general written notice.', source: '225 ILCS 454/15-45(a)' },
  { front: 'What a dual agent cannot disclose', back: 'The price or terms a seller/landlord would actually accept, or a buyer/tenant would actually pay, beyond the listed price -- and no recommended or suggested price/terms to either side -- without that specific party\'s permission.', source: '225 ILCS 454/15-45' },
  { front: 'A seller\'s agent\'s duty to a buyer-customer', back: 'Even representing only the seller, a licensee must still timely disclose latent material adverse facts about the property\'s PHYSICAL condition to a buyer-customer, if the licensee actually knows them and a reasonably diligent inspection wouldn\'t reveal them.', source: '225 ILCS 454/15-25' },
  { front: 'Contemporaneous offers', back: 'Showing the same property to multiple prospective buyers, or preparing competing contemporaneous offers, is NOT itself a breach of duty -- but the licensee must give written disclosure to every affected client, and must refer any client who requests it to a different designated agent.', source: '225 ILCS 454/15-15(b)' },
];

var IL_RE_BROKER_ENFORCEMENT_CONCEPTS_FLASHCARDS = [
  { front: 'Out-of-state discipline as an Illinois ground', back: 'Being disciplined by another state, D.C., a territory, a foreign nation, or another authorized agency is itself a valid Illinois discipline ground -- as long as at least one of the grounds for that other discipline matches or equals an Illinois ground. A certified copy of the other jurisdiction\'s record is enough proof.', source: '225 ILCS 454/20-20(a)(5)' },
  { front: 'Cheating on the exam -- two separate grounds', back: 'A licensee who personally cheats (or tries to subvert) the license exam or a CE exam is disciplinable on that ground alone. Separately, anyone who AIDS or ABETS another applicant\'s cheating is independently disciplinable too -- even without cheating themselves.', source: '225 ILCS 454/20-20(a)(7)-(8)' },
  { front: 'Automatic inactivation on sponsorship loss', back: 'The moment a licensee\'s sponsorship with their sponsoring broker terminates, the license automatically becomes inactive -- no separate Department action is required -- and stays inactive until a new valid sponsorship is registered.', source: '225 ILCS 454/5-40(b)' },
  { front: 'Blind advertisement (statutory definition)', back: 'Any real estate ad that doesn\'t include the sponsoring broker\'s complete business name -- or, for electronic ads, doesn\'t provide a direct link to the required disclosures. A franchise\'s ads must include BOTH the franchise affiliation AND the individual firm\'s own name.', source: '225 ILCS 454/1-10' },
  { front: 'Purely temporary employment as commission evasion', back: 'Employing someone on a purely temporary or single-deal basis specifically as a way to dodge the rule against paying commissions to nonlicensees is its own listed, independent discipline ground.', source: '225 ILCS 454/20-20(a)(23)' },
  { front: 'Child-support delinquency as license leverage', back: 'The Department can refuse, revoke, or suspend a license based SOLELY on a certification from the Department of Healthcare and Family Services that the licensee is more than 30 days delinquent on child support -- no separate real-estate misconduct has to be shown.', source: '225 ILCS 454/20-20(d)' },
  { front: 'Reciprocal-agreement licensing phase-out', back: 'Applications for licensure based on reciprocal agreements with other states stopped being accepted after January 1, 2026. Licenses already granted that way before that date remain valid and renew the same as any other broker or managing broker license.', source: '225 ILCS 454/5-60.1' },
];

var IL_RE_BROKER_FUNDS_RECORDS_FLASHCARDS = [
  { front: 'Real Estate License Administration Fund', back: 'The Department\'s main operating fund under this Act -- ALL fines, penalties, and fees collected under the Act get deposited here first. It funds the Department\'s administration of the Act, including maintaining the separate Recovery Fund, and can transfer money INTO the Recovery Fund as needed.', source: '225 ILCS 454/25-30' },
  { front: 'Real Estate Research and Education Fund', back: 'A THIRD special fund, separate from both the License Administration Fund and the Recovery Fund. Every September 15th it receives a $125,000 transfer, with $15,000 of that specifically earmarked for a real estate scholarship program for historically marginalized classes.', source: '225 ILCS 454/25-25' },
  { front: 'Department staffing minimums', back: 'The Department must employ at least 1 investigator per 10,000 licensees and 1 prosecutor per 20,000 licensees -- a real, statutory enforcement-capacity floor written directly into the Act, not left entirely to budget discretion.', source: '225 ILCS 454/25-20' },
  { front: 'Confidential information (statutory definition)', back: 'Information made confidential by the client\'s written request or instruction, or information about the client\'s negotiating position whose disclosure could materially hurt them. It does NOT include material facts about the property\'s physical condition -- those still have to be disclosed.', source: '225 ILCS 454/1-10' },
  { front: 'Compensation (statutory definition)', back: 'Deliberately broad: commissions, referral fees, bonuses, prizes, merchandise, finder fees, performance of services, coupons/gift certificates, discounts, rebates, a chance to win a raffle/drawing, a retainer fee, or salary. Not just a cash commission at closing.', source: '225 ILCS 454/1-10' },
  { front: 'Recovery Fund investment authority', back: 'Recovery Fund money may be invested and reinvested the same way Illinois PENSION funds are invested under the Illinois Pension Code. Any earnings, interest, or dividends flow back into the License Administration Fund -- not back into the Recovery Fund itself.', source: '225 ILCS 454/25-35' },
];

// ============================================================================
// OH RE SALESPERSON -- Key Facts Digest, drafted 2026-09-03, sourced from ORC
// Chapter 4735 and OAC Chapter 1301:5.
